import { useState, useEffect } from "react";
import { supabase } from "./supabaseClient";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { createClient } from "@supabase/supabase-js";

export default function AdminPanel({ setIsCreatingUser }) {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [users, setUsers] = useState([]);
  // User creation state
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [creating, setCreating] = useState(false);
  const [role, setRole] = useState("staff");
  // PDF Generating state
  const [generatingPdf, setGeneratingPdf] = useState(false);
  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
  const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
  useEffect(() => {
    const fetchStats = async () => {
      const { data, error } = await supabase
        .from("admin_loan_stats")
        .select("*")
        .single();

      if (!error && data) setStats(data);
      setLoading(false);
    };
    fetchStats();
  }, []);

  const fetchUsers = async () => {
    const { data, error } = await supabase
      .from("profiles")
      .select("*")
      .order("created_at", { ascending: false });

    if (!error && data) {
      setUsers(data);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleCreateUser = async (e) => {
    e.preventDefault();
    setCreating(true);

    // 1. Pause the auth listener in App.jsx so the admin isn't kicked out
    if (setIsCreatingUser) setIsCreatingUser(true);

    // 2. Capture the current admin session BEFORE signUp
    const {
      data: { session: adminSession },
    } = await supabase.auth.getSession();

    // 3. Create an isolated client that won't persist the new session to storage
    const tempClient = createClient(supabaseUrl, supabaseAnonKey, {
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    });

    const { data, error } = await tempClient.auth.signUp({
      email,
      password,
    });

    if (error) {
      alert("Error creating user: " + error.message);
    } else {
      // If successful, add them to the profiles table with the chosen role
      if (data.user) {
        await supabase.from("profiles").insert({
          id: data.user.id,
          email: email,
          is_admin: role === "admin", // <-- Set role here
        });
      }

      alert(`User ${email} created successfully as ${role}!`);
      setEmail("");
      setPassword("");
      setRole("staff"); // Reset role dropdown
      fetchUsers(); // Refresh the list
    }

    // 4. Restore the admin session explicitly (safety net)
    if (adminSession) {
      await supabase.auth.setSession({
        access_token: adminSession.access_token,
        refresh_token: adminSession.refresh_token,
      });
    }

    // 5. Let auth events flush, then re-enable the listener
    setTimeout(() => {
      if (setIsCreatingUser) setIsCreatingUser(false);
    }, 100);

    setCreating(false);
  };

  // Generate PDF Function
  const downloadPdf = async () => {
    setGeneratingPdf(true);

    // Fetch ALL records for the PDF
    const { data, error } = await supabase
      .from("loan_customers")
      .select(
        "loan_id, full_name, mobile_number, bank_partner, loan_amount, status, created_at",
      )
      .order("created_at", { ascending: false });

    if (error) {
      alert("Failed to fetch data for PDF");
      setGeneratingPdf(false);
      return;
    }

    // Setup PDF Document
    const doc = new jsPDF("landscape"); // Landscape fits more columns
    const logoBase64 =
      "data:image/png;base64,";
    // Add Title & Date

    try {
      doc.addImage(logoBase64, "PNG", 14, 10, 20, 20);
    } catch (e) {
      console.log("Logo failed to load in PDF");
    }
    doc.setFontSize(18);
    doc.setTextColor(15, 23, 42); // Dark Slate
    doc.setFont("helvetica", "bold");
    doc.text("Real Money - Loan Applications Report", 40, 20);

    // 3. Set Date Text (Moved X to 40 to align with Title)
    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.setFont("helvetica", "normal");
    doc.text(`Generated on: ${new Date().toLocaleString()}`, 40, 28);

    // Format data for the table
    const tableColumn = [
      "Loan ID",
      "Customer Name",
      "Mobile",
      "Bank",
      "Amount (INR)",
      "Status",
      "Date",
    ];
    const tableRows = data.map((c) => [
      c.loan_id || "-",
      c.full_name,
      c.mobile_number || "-",
      c.bank_partner || "-",
      c.loan_amount ? Number(c.loan_amount).toLocaleString("en-IN") : "0",
      c.status.toUpperCase(),
      new Date(c.created_at).toLocaleDateString(),
    ]);

    // 4. Generate Table (startY: 35 gives 15px gap below the header text)
    autoTable(doc, {
      head: [tableColumn],
      body: tableRows,
      startY: 36,
      theme: "striped",
      styles: { fontSize: 9, cellPadding: 3 },
      headStyles: { fillColor: [20, 184, 166] }, // Teal color
      margin: { left: 14, right: 14 }, // Keeps the table aligned with the logo
    });

    doc.save(`Real_Money_Report_${new Date().toISOString().split("T")[0]}.pdf`);
    setGeneratingPdf(false);
  };

  return (
    <div className="space-y-6">
      {/* Global Statistics */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-slate-900">
            System-Wide Overview
          </h2>

          {/* PDF Download Button */}
          <button
            onClick={downloadPdf}
            disabled={generatingPdf}
            className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-400 text-white font-medium py-2 px-4 rounded-lg transition shadow-sm flex items-center gap-2 text-sm"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
              />
            </svg>
            {generatingPdf ? "Generating PDF..." : "Download Full PDF Report"}
          </button>
        </div>

        {loading ? (
          <p className="text-slate-500">Loading global stats...</p>
        ) : stats ? (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="bg-slate-50 border border-slate-200 rounded-xl p-5">
              <p className="text-sm font-medium text-slate-500">
                Total Applications
              </p>
              <p className="text-3xl font-bold text-slate-900 mt-1">
                {stats.total_applications || 0}
              </p>
            </div>
            <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-5">
              <p className="text-sm font-medium text-emerald-700">
                Approved Loans
              </p>
              <p className="text-3xl font-bold text-emerald-800 mt-1">
                {stats.total_approved || 0}
              </p>
              <p className="text-xs text-emerald-600 mt-1 font-medium">
                ₹ {stats.total_amount_approved?.toLocaleString("en-IN") || 0}
              </p>
            </div>
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-5">
              <p className="text-sm font-medium text-amber-700">Pending</p>
              <p className="text-3xl font-bold text-amber-800 mt-1">
                {stats.total_pending || 0}
              </p>
            </div>
            <div className="bg-rose-50 border border-rose-200 rounded-xl p-5">
              <p className="text-sm font-medium text-rose-700">Rejected</p>
              <p className="text-3xl font-bold text-rose-800 mt-1">
                {stats.total_rejected || 0}
              </p>
            </div>
          </div>
        ) : (
          <p className="text-rose-500">
            Failed to load stats. Are you an admin?
          </p>
        )}
      </div>

      {/* Add New User Form */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8 max-w-2xl">
        <h2 className="text-xl font-bold text-slate-900 mb-2">
          Add New Account
        </h2>
        <p className="text-sm text-slate-500 mb-6">
          Create credentials for employees or new administrators.
        </p>

        <form onSubmit={handleCreateUser} className="space-y-5">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Email Address
              </label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-teal-500 outline-none transition"
                placeholder="user@office.com"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Temporary Password
              </label>
              <input
                type="password"
                required
                minLength={6}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-teal-500 outline-none transition"
                placeholder="At least 6 characters"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">
              Account Role
            </label>
            <select
              value={role}
              onChange={(e) => setRole(e.target.value)}
              className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-teal-500 outline-none transition cursor-pointer"
            >
              <option value="staff">Staff Member</option>
              <option value="admin">Administrator</option>
            </select>
          </div>

          <button
            type="submit"
            disabled={creating}
            className="w-full bg-slate-900 hover:bg-slate-800 text-white font-semibold py-3 rounded-xl transition shadow-sm"
          >
            {creating ? "Creating Account..." : "Create Account"}
          </button>
        </form>
      </div>

      {/* Registered Users List */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8">
        <h2 className="text-xl font-bold text-slate-900 mb-6">
          Registered Users
        </h2>

        <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
          {users.length === 0 ? (
            <p className="text-slate-500 text-sm">No users found.</p>
          ) : (
            users.map((u) => (
              <div
                key={u.id}
                className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-xl"
              >
                <div>
                  <p className="font-medium text-slate-800">
                    {u.email || "No email"}
                  </p>
                  <p className="text-xs text-slate-400 mt-1 font-mono">
                    {u.id.split("-")[0]}...
                  </p>
                </div>
                <span
                  className={`px-2 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md ${
                    u.is_admin
                      ? "bg-indigo-100 text-indigo-700"
                      : "bg-emerald-100 text-emerald-700"
                  }`}
                >
                  {u.is_admin ? "Admin" : "Staff"}
                </span>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}
